SELECT * FROM (SELECT CASE WHEN unit_price >= 360 THEN 'high' WHEN unit_price >= 190 THEN 'mid' ELSE 'low' END AS unit_price_bucket, SUM(unit_price) AS total_unit_price, SUM(unit_price * quantity) AS revenue FROM order_items WHERE order_id IN (8, 14, 16, 38) GROUP BY CASE WHEN unit_price >= 360 THEN 'high' WHEN unit_price >= 190 THEN 'mid' ELSE 'low' END) AS s WHERE revenue < 77 ORDER BY revenue
